<template>
<div class="app-review sf-ui" :class="{'customer-mode':!reviewMode}">
  <aside v-if="reviewMode" class="review-rail">
    <router-link class="review-back" to="/commercialization/overview">← SunnyFit Admin</router-link><div class="review-kicker">SUNNYFIT 3.0 · DESIGN REVIEW</div><h1>商业化任务验证</h1><p class="review-intro">V3.0 材质与控件体系；会员部分依据业务原型重新设计，保留既有入口。价格、额度数量和单次消耗为本地评审参数；功能权益不消耗 Credits。支付与分析为模拟服务。</p>
    <label for="scenario-user">演示用户</label><select id="scenario-user" v-model="userId" :disabled="busy" @change="changeUser"><option v-for="u in users" :key="u.id" :value="u.id">{{ u.name }} · {{ u.scenario }}</option></select>

    <div v-if="flowState" class="review-feedback" role="status">{{ flowState }}</div>
    <div v-if="sourceGap" class="review-feedback" role="status">{{ sourceGap }}</div>
    <nav class="review-pages"><button v-for="item in pages" :key="item.id" :class="{selected:screen===item.id}" :aria-current="screen===item.id?'page':null" @click="go(item.id)">{{ item.label }}</button></nav><membership-review-controls v-if="['profile','membership','course','world-tour','program','weekly','coach','plan','challenge','result'].includes(screen)" :page-options="mvpOptions" :member="mvpMember" :purchase-outcome="mvpPurchaseOutcome" @purchase-outcome="mvpPurchaseOutcome=$event"/>
    <section v-if="screen==='movement-training'" class="movement-review-controls"><h3>视觉训练 · 场景控制</h3><label>画面源<select v-model="movementReview.source"><option value="demo">示例画面（模拟识别事件）</option><option value="camera">真实摄像头（本地识别）</option></select></label><label>设备能力<select v-model="movementReview.performance"><option value="auto">自动判定</option><option value="low">低性能机型</option></select></label><label v-if="movementReview.source==='demo'" class="review-checkbox"><input v-model="movementReview.framed" type="checkbox">模拟检测到人入镜</label><template v-if="movementReview.source==='demo'&&movementView.stage==='training'"><button @click="$refs.movement.simulate('rep')">模拟识别 +1 次</button><button @click="$refs.movement.simulate('target')">模拟识别至本动作目标</button><button @click="$refs.movement.simulate('timer')">计时动作 · 剩余 1 秒</button></template><p>示例画面不触发真实识别。仅评审控件注入识别事件；计时动作正常推进。摄像头图像不上传。</p><router-link v-if="movementContent" :to="'/commercialization/content/'+movementContent.id">编辑训练组合与视觉配置 ↗</router-link></section>
    <div class="review-note"><h3>{{ note.title }}</h3><p v-for="(line,i) in note.lines" :key="i">{{ line }}</p></div>
    <div class="review-tools"><label class="review-checkbox"><input v-model="commercial" type="checkbox">显示商业化标记</label><label v-if="screen==='coach'" class="review-checkbox"><input v-model="sampleConversation" type="checkbox">查看原稿示例对话</label><label class="review-checkbox"><input v-model="simulateFailure" type="checkbox">模拟 LLM 失败并释放额度</label><label for="demo-content">内容场景</label><select id="demo-content" v-model="contentId" :disabled="busy" @change="updateBinding"><option v-for="c in data?data.contents:[]" :key="c.id" :value="c.id">{{ c.tier }} · {{ c.name }}</option></select><label for="demo-program">Training Program</label><select id="demo-program" v-model="programId" @change="updateBinding"><option v-for="p in programContents" :key="p.id" :value="p.id">{{ p.name }}</option></select><button :disabled="busy" @click="load">刷新后台数据</button><button @click="go(screen,{review:'0'})">进入用户模式</button><router-link :to="'/commercialization/users/'+userId">查看后台记录 ↗</router-link></div>
  </aside>
  <main v-fit-preview class="phone-stage"><div class="phone-frame" :class="{'account-frame':['profile','membership','plans','billing','wallet'].includes(screen)||isProfileSecondary,'membership-frame':screen==='membership','profile-frame':screen==='profile','challenge-frame':screen==='challenge','home-frame':screen==='home','movement-frame':['movement-detail','movement-training'].includes(screen),'movement-landscape':screen==='movement-training'&&movementView.landscape,'native-frame':['home','workout','course','plan','program','history'].includes(screen)}" :aria-busy="loading?'true':'false'" :style="{'--canvas-height':canvasHeight+'px'}">
    <div v-if="loading&&!data" class="mobile-loading">Loading…</div><div v-if="error&&!data" class="mobile-error" role="alert">{{ error }}<button @click="load">Retry</button></div>
    <template v-else-if="data">
      <div v-if="mvpPageFeedback" class="mvp-native-viewport"><mvp-page-feedback :title="screenTitle" :state="mvpPageState" @action="handleAction"/></div><div v-else-if="isSourceScreen" ref="sourceViewport" class="source-viewport" :class="'viewport-'+screen"><source-canvas :screen="screen" :user="data.user" :report="presentationData.weeklyReport" :ai-state="mvpAiState" :input-locked="mvpInputLocked" :mvp-member="(isMvpPreview||data.policyVersion===20261014)?mvpMember:null" :mvp-state="mvpPageState" :name="data.user.name" :message="message" :messages="sessionResults.filter(s=>s.type==='conversation')" :insight-body="mvpInsightBody" :opened-asset="openedConversation" :context="coachContext" :balance="data.wallet.available" :commercial="commercial" :sample-conversation="sampleConversation" :has-insight="mvpHasInsight" :analysis-credits="serviceCost('deep_analysis')" :chat-credits="serviceCost('ai_chat')" :tier="displayContent.tier" :content="displayContent" :courses="courseContents" :workout="programWorkout" :next-workout="nextProgramWorkout" :charge-label="costLabel('deep_analysis')" :chat-label="mvpChatLabel" :redemption-credits="displayContent.redemptionCredits||0" @input="setMessage" @action="handleAction"/></div>
      <div v-else-if="screen==='weekly'" class="mvp-native-viewport"><v3-weekly-report :report="presentationData.weeklyReport" :user="data.user" :busy="busy" @action="handleAction"/></div>
      <div v-else-if="screen==='challenge'" class="mvp-native-viewport"><v3-challenge :contents="challengeContents" :user="data.user" :busy="busy" @action="handleAction"/></div>
      <div v-else-if="['movement-detail','movement-training'].includes(screen)" class="mvp-native-viewport"><movement-experience v-if="movementContent" ref="movement" :key="userId+movementContent.id+screen" :initial-stage="screen==='movement-detail'?'detail':'prepare'" :content="movementContent" :busy="busy" :review="reviewMode" :review-options="movementReview" @start="authorizeMovement" @prepare="go('movement-training')" @exit="go(screen==='movement-detail'?'movement':'movement-detail')" @complete="go('movement')" @view-state="movementView=$event"/></div>
      <div v-else-if="screen==='movement'||screen==='world-tour'" class="mvp-native-viewport"><v3-content-collection :kind="screen==='movement'?'movement':'world_tour'" :contents="collectionContents" :busy="busy" @action="handleAction"/></div>
      <div v-else-if="screen==='history'" class="history-screen history-screen--native"><sf-page-layout title="Coach history" @back="go('coach')"><sf-menu-row v-for="asset in conversations" :key="asset.id" :label="asset.title" :description="shortDate(asset.createdAt)" @click="readConversation(asset)"/><sf-feedback v-if="!conversations.length" tone="empty" title="No conversations yet" description="Your saved conversations will appear here." action="Open AI Coach" @action="go('coach')"/></sf-page-layout></div>
      <template v-else><header class="app-account-top sf-top-bar-mask"><div class="source-status"><b>9:41</b></div><sf-header v-if="screen!=='profile'" class="mobile-header" :title="screenTitle" glass @back="back"/></header><div ref="accountScroll" class="mobile-scroll"><personal-center v-if="screen==='profile'" :data="data" @go="go" @retry="load"/><profile-secondary v-else-if="isProfileSecondary" :key="data.user.id+':'+screen+':'+($route.query.profileSection||'')+':'+($route.query.profileItem||'')" :screen="screen" :section="$route.query.profileSection" :item="$route.query.profileItem" :parent="$route.query.profileParent" :data="data" @go="go" @retry="load"/><membership-usage v-else-if="screen==='membership'" :data="data" :locale="locale" :busy="busy" @go="go" @restore="restoreMvpPurchases" @retry="load" @subscribe="mvpUpgrade('membership')"/><consumer-screens v-else :data="data" :screen="screen" :credit-type="$route.query.creditType" :locale="locale" :busy="busy" @checkout="checkout" @renew="renew" @restore="restore" @ledger="showLedger=true"/><button v-if="returnTo" class="mobile-primary" @click="returnToFlow">Return to {{ returnTitle }}</button></div></template>
      <div v-if="error" class="source-error" role="alert">{{ error }}<button @click="error=''" aria-label="Dismiss error">×</button></div>
      <div v-if="sourceGap&&!reviewMode" class="source-section-feedback"><sf-toast :open="!!sourceGap" message="This section isn't available in this preview yet." @input="sourceGap=''"/></div>
      <mvp-upgrade-sheet :gate="mvpGate" :member="mvpMember" :offers="mvpOffers" @close="cancelMvpPurchase" @purchase="purchaseMvpOffer" @resume="resumeMvpPurchase" @retry="retryMvpPurchase" @check="checkMvpPurchase" @usage="viewMvpUsage" @refresh="refreshMvpAllowance"/><commerce-sheets :app="sheetContext" @close="closeSheet" @resolve="resolveGate" @purchase="confirmPurchase" @service="runService" @redeem="confirmRedemption" @renew="applyRenewal" @done="finishNotice" @workout="openProgramWorkout"/>
      <sf-toast :open="!!appToast" :message="appToast" @input="appToast=''"/>
      <button v-if="mvpPendingPurchase&&!mvpGate" type="button" class="mvp-purchase-pending" @click="mvpGate=mvpPendingPurchase">Purchase confirmation pending · Check status</button>
    </template>
  </div><p v-if="reviewMode" class="phone-caption">{{ screenTitle }} · Demo 评审</p></main>
</div>
</template>
<script>
import controller from './controller'
import MvpPageFeedback from './MvpPageFeedback'
import MvpUpgradeSheet from './ContextualSubscription'
import MembershipReviewControls from './MembershipReviewControls'
import fitPreview from '@/demo/fit-preview'
import CommerceSheets from './CommerceSheets'
import {SfHeader,SfToast,SfPageLayout,SfMenuRow,SfFeedback} from '@/design-system'
export default {...controller,directives:{fitPreview},components:{...controller.components,MvpPageFeedback,MvpUpgradeSheet,MembershipReviewControls,CommerceSheets,SfHeader,SfToast,SfPageLayout,SfMenuRow,SfFeedback},computed:{...controller.computed,sheetContext(){return {...this.$data,displayContent:this.displayContent,returnTo:this.returnTo,returnTitle:this.returnTitle,money:this.money,shortDate:this.shortDate,serviceLabel:this.serviceLabel,cadenceLabel:this.cadenceLabel,eventLabel:this.eventLabel}}}}
</script>
<style scoped>.mvp-native-viewport{height:100%;position:relative;min-width:0;overflow:hidden}</style>
